// Four additional exam-standard AgilePM v3 Foundation mock papers (6–9).
// Same APMG style and syllabus weighting as HARD_EXAMS. Questions are
// original, grounded in the v3 reference book, and written to be harder
// than Papers 1–5 (artifact RACI, PAQ remedies, estimating cycle, lifecycle
// configurations, and easy-to-confuse role/optionality traps).

export const EXTRA_HARD_EXAMS = [
  {
    id: 'hardF',
    title: 'Full Mock Exam 6',
    questions: [
      { id: 'P6Q1', topic: 'KC', q: 'Who introduced Rapid Application Development (RAD) in 1991, and what later problem did DSDM exist to correct?', options: ['James Martin; quick fixes hurt quality because teams moved straight into development without enough analysis and design', 'Ken Schwaber; teams produced too much documentation', 'Frederick Taylor; workers were treated like machines', 'Arie van Bennekum; contracts became too flexible'], correct: 'James Martin; quick fixes hurt quality because teams moved straight into development without enough analysis and design', explain: 'RAD (James Martin, 1991) favoured speed; DSDM restored control and quality while keeping iteration and business involvement (Ch.1).' },
      { id: 'P6Q2', topic: 'KC', q: 'Identify the missing name. The Manifesto for Agile Software Development included [ ? ], who was part of the team behind what later became AgilePM.', options: ['Arie van Bennekum', 'Barry Boehm', 'Rachel Davies', 'Geoff Watts'], correct: 'Arie van Bennekum', explain: 'Arie van Bennekum was a Manifesto signatory and part of the team behind AgilePM/DSDM (2.1.3).' },
      { id: 'P6Q3', topic: 'KC', q: 'Which of the following statements, about Scrum and AgilePM, are true?\n1. Scrum\u2019s roles, artefacts, events and rules are treated as unchangeable \u2014 all must be present to be using Scrum\n2. AgilePM\u2019s guidance is intended to be flexible and tailored to each organisation\u2019s context', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Scrum\u2019s structure is fixed; AgilePM is expected to be tailored (2.4 / 3.1).' },
      { id: 'P6Q4', topic: 'KC', q: 'What does AgilePM mean by \u2018latent value\u2019?', options: ['The potential value of a product, realised only when the product is actually in use', 'Value written into the Business Case but never measured', 'Value lost when a Solution Increment is delayed', 'The unused contingency held in Could Have requirements'], correct: 'The potential value of a product, realised only when the product is actually in use', explain: 'A solution-focused view exists so latent value is captured once the product is used (2.2).' },
      { id: 'P6Q5', topic: 'KC', q: 'Which of the following are characteristics AgilePM says agile contracts should have?\n1. Co-created by those who will use them\n2. Focused on success rather than assigning blame\n3. Designed to enforce a rigid, unchanging scope\n4. Supportive of an ongoing customer relationship as requirements evolve', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Agile contracts must allow flexibility; they are not for enforcing rigid scope (2.1.3).' },
      { id: 'P6Q6', topic: 'SC', q: 'What must happen to the current Product Goal before the Scrum Team takes on the next one?', options: ['It must be fulfilled or abandoned', 'It must be signed off by the Business Sponsor', 'It must be converted into a Sprint Goal', 'It must be added to the Definition of Done'], correct: 'It must be fulfilled or abandoned', explain: 'The Product Goal is the long-term objective and must be fulfilled or abandoned before the next is taken on (3.6).' },
      { id: 'P6Q7', topic: 'SC', q: 'Which of the following statements, about adapting the plan during a Sprint, are true?\n1. The Daily Scrum is the only time Developers may adjust their plan\n2. Developers often meet throughout the day for more detailed discussions', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'The Daily Scrum is not the only inspect-and-adapt point; Developers may meet as needed (3.5).' },
      { id: 'P6Q8', topic: 'SC', q: 'Identify the missing words. Adaptation becomes more difficult when people are not [ ? ].', options: ['empowered or self-managing', 'co-located in one office', 'certified Scrum Masters', 'given a fixed specification'], correct: 'empowered or self-managing', explain: 'Adaptation should occur as soon as possible; it is harder without empowerment (3.2).' },
      { id: 'P6Q9', topic: 'SC', q: 'Which of the following are Developer accountabilities in Scrum?\n1. Creating a plan for the Sprint (the Sprint Backlog)\n2. Instilling quality by adhering to the Definition of Done\n3. Owning the Product Goal on behalf of stakeholders\n4. Holding each other accountable as professionals', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Developers plan, instil quality and hold each other accountable; the Product Goal is managed by the Product Owner (3.4).' },
      { id: 'P6Q10', topic: 'SC', q: 'How does the Scrum Master serve the Product Owner?', options: ['By helping find techniques for effective Product Goal definition and empirical product planning', 'By ordering the Product Backlog when the Product Owner is unavailable', 'By cancelling the Sprint if the Product Goal looks at risk', 'By presenting the Increment at the Sprint Review on the Product Owner\u2019s behalf'], correct: 'By helping find techniques for effective Product Goal definition and empirical product planning', explain: 'The Scrum Master serves the Product Owner with techniques, clarity of items, empirical planning and stakeholder collaboration \u2014 not by taking Product Owner decisions (3.4).' },
      { id: 'P6Q11', topic: 'SC', q: 'Which statement about a Product Increment is true?', options: ['Each Increment is additive to all prior Increments and must be thoroughly verified and usable', 'An Increment may be presented at the Sprint Review even if it does not meet the Definition of Done', 'Only one Increment may exist during a Sprint', 'An Increment is born when Sprint Planning is completed'], correct: 'Each Increment is additive to all prior Increments and must be thoroughly verified and usable', explain: 'Increments are additive, verified and usable; undone items cannot be presented at the Review (3.6).' },
      { id: 'P6Q12', topic: 'AF', q: 'Which of the following are foundational elements of the AgilePM framework?\n1. Process\n2. People\n3. Planning horizons\n4. Practices', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The four are Process, People, Project Artifacts and Practices \u2014 planning horizons are a Chapter 10 concept (4.1).' },
      { id: 'P6Q13', topic: 'AF', q: 'Under \u2018Demonstrate Control\u2019, why does AgilePM say a partially completed feature has less business value than a feature not started?', options: ['Incomplete work adds complications without adding usable value', 'Started work always consumes the Must Have contingency', 'The Definition of Done forbids starting a second feature', 'Parkinson\u2019s Law only applies to unfinished tasks'], correct: 'Incomplete work adds complications without adding usable value', explain: 'Progress is tracked on working solutions; incomplete work complicates delivery without adding value (4.3).' },
      { id: 'P6Q14', topic: 'AF', q: 'Identify the missing word. Pragmatism in AgilePM means making decisions that adapt to [ ? ] rather than following rigid rules or procedures.', options: ['real-life situations', 'the original contract', 'the sponsor\u2019s first estimate', 'a sequential lifecycle'], correct: 'real-life situations', explain: 'Pragmatism = adapting to real-life situations; common sense = practical judgment over unnecessary complexity (4.1).' },
      { id: 'P6Q15', topic: 'AF', q: 'Documentation should be created only when which of the following apply?\n1. It adds value to organisational or user understanding\n2. It helps with solution development and support\n3. It is produced because the methodology requires a full document set\n4. It is essential for safety-critical or regulatory compliance', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Principle 7: create documents only if they add value, aid development/support, or are essential for safety/regulation (4.3).' },
      { id: 'P6Q16', topic: 'AF', q: 'Which of the following statements, about what AgilePM can manage beyond Scrum, are true?\n1. AgilePM can manage business-related work not directly linked to product development, such as business process change\n2. Scrum alone already provides project-level financial and regulatory governance', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'AgilePM adds lifecycle, governance and roles around Scrum, including non-product business change (4.4).' },
      { id: 'P6Q17', topic: 'IN', q: 'Which three Project Role domains does AgilePM define?', options: ['Value Ownership, Solution Delivery and Delivery Enablement', 'Project Leadership, Finance and Assurance', 'Product, Process and People', 'Governance, Compliance and Delivery'], correct: 'Value Ownership, Solution Delivery and Delivery Enablement', explain: 'Business Sponsor/Visionary sit in Value Ownership, Solution Architect in Solution Delivery, Project Manager in Delivery Enablement (5.2).' },
      { id: 'P6Q18', topic: 'IN', q: 'At which two levels may a Business Analyst be needed, according to AgilePM?', options: ['Strategic (assisting executives in shaping strategy) and operational (defining detailed acceptance criteria)', 'Portfolio only, and only during Pre-Project', 'Sprint Planning only, and only as Scrum Master', 'Deployment only, and only as Process Advisor'], correct: 'Strategic (assisting executives in shaping strategy) and operational (defining detailed acceptance criteria)', explain: 'Business analysis spans C-suite strategy and operational acceptance criteria; a BA working as a Developer may support backlog management (5.4).' },
      { id: 'P6Q19', topic: 'IN', q: 'Which of the following statements, about scaled support of Delivery Teams, are true?\n1. Good practice suggests an experienced Product Owner may support up to three teams if they share a single Product Backlog\n2. A Scrum Master may effectively support up to three teams', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Both Product Owner and Scrum Master guidance allows support of up to three teams in the right conditions (5.4).' },
      { id: 'P6Q20', topic: 'IN', q: 'Which of the following are the four factors AgilePM says influence how external stakeholders interact?\n1. Purpose\n2. Timing\n3. Seniority grade\n4. Authority', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The four are Purpose, Timing, Authority and Constraints \u2014 not seniority grade (5.2).' },
      { id: 'P6Q21', topic: 'IN', q: 'Identify the missing words. The Scrum Guide\u2019s idea of \u2018true leadership\u2019 is that success is defined by [ ? ].', options: ['the effectiveness of the Delivery Team(s)', 'the volume of reports produced', 'the Project Manager\u2019s personal decisions', 'how closely the original plan is followed'], correct: 'the effectiveness of the Delivery Team(s)', explain: 'True leadership develops others so the team is as effective as it can be (5.3.6).' },
      { id: 'P6Q22', topic: 'IN', q: 'Which Advisor role is typically fulfilled by an Agile Coach or a Workshop Facilitator?', options: ['Process Advisor', 'Business Advisor', 'Solution Advisor', 'Governance Advisor'], correct: 'Process Advisor', explain: 'Process Advisors provide agile-framework expertise; there is no Governance Advisor role (5.2).' },
      { id: 'P6Q23', topic: 'IN', q: 'Which of the following statements, about the Business Sponsor, are true?\n1. The Business Sponsor is always a single person, though they may represent a steering or executive committee\n2. Financial accountabilities may sit with a higher authority such as an investment board', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'The role is always one person; they may represent a governing group and finance may sit higher (5.3.1).' },
      { id: 'P6Q24', topic: 'CC', q: 'On the Aligned Autonomy Matrix, what does LOW alignment combined with HIGH autonomy produce?', options: ['An entrepreneurial organisation with a chaotic culture', 'An innovative organisation with a collaborative culture', 'An authoritative organisation with an authoritarian culture', 'A bureaucratic organisation with an indifferent culture'], correct: 'An entrepreneurial organisation with a chaotic culture', explain: 'Low alignment + high autonomy = entrepreneurial/chaotic; high/high = innovative/collaborative (Fig. 6.1).' },
      { id: 'P6Q25', topic: 'CC', q: 'Which of the following are benefits AgilePM lists for collaboration?\n1. Improved problem-solving\n2. Improved (experiential) learning\n3. Reduced need for any communication\n4. Increased productivity', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The four benefits are problem-solving, learning, productivity and cross-functional learning \u2014 not less communication (6.2).' },
      { id: 'P6Q26', topic: 'CC', q: 'Which of the following statements, about commitments and documents, are true?\n1. A verbal commitment made in a group can be stronger than signing a document\n2. A risk only becomes real once it has been formally logged', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Risks and assumptions are real whether written or not; a group verbal commitment is often stronger than a signature (6.4).' },
      { id: 'P6Q27', topic: 'CC', q: 'When is instant messaging described as a useful communication choice?', options: ['For quick exchanges of short messages, especially when seeing who is online matters', 'As the richest replacement for a facilitated workshop', 'As the primary method for resolving complex conflict', 'Only when a formal audit trail is required by regulators'], correct: 'For quick exchanges of short messages, especially when seeing who is online matters', explain: 'Chat suits short, timely exchanges; encrypted apps are used where privacy is essential (6.3).' },
      { id: 'P6Q28', topic: 'PR', q: 'During Feasibility, which combination of artifact optionality is correct?', options: ['Business Case and Management Approach Definition are recommended; Solution Architecture Definition and Delivery Approach Definition are optional', 'All Feasibility artifacts are required', 'The Delivery Plan is required in Feasibility; the Business Case is optional', 'Only the Terms of Reference is produced in Feasibility'], correct: 'Business Case and Management Approach Definition are recommended; Solution Architecture Definition and Delivery Approach Definition are optional', explain: 'Feasibility: Business Case recommended, Solution Backlog optional, SAD optional, DAD optional, MAD recommended (7.3).' },
      { id: 'P6Q29', topic: 'PR', q: 'Identify the missing words. At Feasibility, only rough cost estimates are needed \u2014 typically around [ ? ] accuracy.', options: ['+/- 50%', '+/- 10%', '+/- 5%', 'exact actuals'], correct: '+/- 50%', explain: 'Further detail is deferred to Foundations; Feasibility uses rough ranges such as +/- 50% (7.3).' },
      { id: 'P6Q30', topic: 'PR', q: 'Which of the following statements, about slices of a Product Increment, are true?\n1. A \u2018vertical\u2019 Done slice contains all required layers so it can be used\n2. Delivering only a \u2018horizontal\u2019 technology layer is still beneficial because later Sprints can add the other layers', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Horizontal layers delay value and risk integration problems; prefer vertical, usable slices (7.5).' },
      { id: 'P6Q31', topic: 'PR', q: 'Who is responsible for embedding the solution so benefits are realised, and who is accountable for the return on investment?', options: ['Business Visionary is responsible for realisation; Business Sponsor is accountable for ROI', 'Project Manager is responsible for realisation; Product Owner is accountable for ROI', 'Solution Architect is responsible for realisation; Scrum Master is accountable for ROI', 'Product Owner is responsible for realisation; Business Visionary is accountable for ROI'], correct: 'Business Visionary is responsible for realisation; Business Sponsor is accountable for ROI', explain: 'The Business Visionary embeds the solution; the Business Sponsor is accountable for return on investment (7.7).' },
      { id: 'P6Q32', topic: 'PR', q: 'Which lifecycle configuration includes an active \u2018firebreak\u2019 to return to Foundations and plan the next Project Increment?', options: ['A multi-increment delivery lifecycle with deployments several times each Sprint', 'A simple single-increment lifecycle with one deployment after a series of Sprints', 'A continuous-delivery lifecycle with no return to Foundations', 'A Pre-Project only lifecycle used for portfolio ranking'], correct: 'A multi-increment delivery lifecycle with deployments several times each Sprint', explain: 'Example 3 uses a firebreak back to Foundations; Example 4 has no such return (7.2 / Fig. 7.7).' },
      { id: 'P6Q33', topic: 'ES', q: 'What is the hierarchy of backlogs described in AgilePM?', options: ['Solution Backlog \u2192 Product Backlog \u2192 Sprint Backlog', 'Sprint Backlog \u2192 Product Backlog \u2192 Solution Backlog', 'Product Backlog \u2192 Business Case \u2192 Sprint Backlog', 'Terms of Reference \u2192 Delivery Plan \u2192 Team Board'], correct: 'Solution Backlog \u2192 Product Backlog \u2192 Sprint Backlog', explain: 'Figure 8.2: the Solution Backlog feeds Product Backlogs, which feed Sprint Backlogs (8.1).' },
      { id: 'P6Q34', topic: 'ES', q: 'Who invented the widely used \u2018As a <role>, I want <feature>, so that <value>\u2019 User Story format?', options: ['Rachel Davies', 'Mike Cohn', 'Dan North', 'Jeff Patton'], correct: 'Rachel Davies', explain: 'Rachel Davies invented the format; Mike Cohn popularised User Stories; Dan North created BDD; Jeff Patton created Story Mapping (8.2.3).' },
      { id: 'P6Q35', topic: 'ES', q: 'Which of the following statements, about MoSCoW dependencies, are true?\n1. A Must Have must not depend on a Should Have or Could Have, because those might not be delivered\n2. MoSCoW categories mandate the order in which work must be started', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'MoSCoW describes importance, not delivery order; a Must Have cannot depend on a lower priority (9.4 / 9.8.1).' },
      { id: 'P6Q36', topic: 'ES', q: 'How does commitment-based planning estimate a team\u2019s velocity when little historic data exists?', options: ['Developers pull the next backlog item only while they can still commit to finishing it this Sprint, and stop when someone says it is too much', 'The Project Manager assigns a target number of story points', 'The Business Sponsor selects a figure from the Cone of Uncertainty', 'Velocity is copied from another team doing similar work'], correct: 'Developers pull the next backlog item only while they can still commit to finishing it this Sprint, and stop when someone says it is too much', explain: 'Commitment-based planning is team-driven; velocity is unique to each team and measures output, not outcome (8.3.3.3).' },
      { id: 'P6Q37', topic: 'ES', q: 'Which of the following statements, about Epic User Stories in Feasibility, are true?\n1. They are typically fewer than ten very high-level stories that define project scope\n2. They should be clear enough to judge feasibility, cost and benefit\n3. An estimating-by-analogy technique (for example T-shirt sizing) is commonly used\n4. They are usually estimated in story points rather than time', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Feasibility Epics are few, high-level and estimated in time ranges (for example 3\u20136 months), not story points (8.2 / 8.3.5.1).' },
      { id: 'P6Q38', topic: 'ES', q: 'Why does AgilePM warn against forcing a team to commit to delivering every Must, Should and Could Have?', options: ['It often leads to inflated estimates with hidden contingency padding', 'It is the only way to protect the Minimum Usable Subset', 'It is required by the Project Approach Questionnaire', 'It replaces the need for a Business Case'], correct: 'It often leads to inflated estimates with hidden contingency padding', explain: 'Forcing a full-scope commitment looks successful but hides padding; plans cannot guarantee Shoulds and Coulds (9.6).' },
      { id: 'P6Q39', topic: 'PC', q: 'By the end of Foundations, the Delivery Plan for the next (or only) Project Increment is typically how long, expressed as what?', options: ['Typically 6\u201312 weeks, as a high-level schedule of Sprints with speculative Sprint Goals', 'Typically 6 months of task-level Gantt detail', 'A single two-week Sprint with no further outline', 'A multi-year portfolio roadmap owned by the Developers'], correct: 'Typically 6\u201312 weeks, as a high-level schedule of Sprints with speculative Sprint Goals', explain: 'Foundations produces a high-level increment plan of about 6\u201312 weeks; detailed Sprint planning stays with the teams (10.2.2.2).' },
      { id: 'P6Q40', topic: 'PC', q: 'Which of the following statements, about Cross-Team Refinement (CTR), are true?\n1. It should take place at least once every Sprint, typically lasting 1\u20133 hours\n2. It inspects Project Artifacts as well as Product Backlog items\n3. The Business Sponsor must always facilitate it\n4. Effective CTR may reduce the need to return to Foundations between increments', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'CTR is at least once per Sprint, 1\u20133 hours, inspects project artifacts, and may negate a Foundations revisit (10.2.3.6.1).' },
      { id: 'P6Q41', topic: 'PC', q: 'What is a Scrum of Scrums primarily used for on an AgilePM project?', options: ['Representatives from each team meet every few days to share updates, especially where dependencies exist', 'The Business Sponsor reviews individual Developer performance', 'Replacing the Daily Scrum for every team', 'Creating the Business Case'], correct: 'Representatives from each team meet every few days to share updates, especially where dependencies exist', explain: 'A Scrum of Scrums is an optional cross-team alignment activity; it is not the only time teams may interact (10.2.3.6.2).' },
      { id: 'P6Q42', topic: 'PC', q: 'Identify the missing words. The Project Sprint Review timebox can be the same as a regular one-month Sprint \u2014 a maximum of 4 hours, or [ ? ].', options: ['an hour for each week of the Sprint', 'fifteen minutes regardless of Sprint length', 'eight hours for every team involved', 'as long as the Business Sponsor requires'], correct: 'an hour for each week of the Sprint', explain: 'The Review scales with Sprint length: max 4 hours for a one-month Sprint, roughly one hour per week (10.2.3.7).' },
      { id: 'P6Q43', topic: 'PC', q: 'In AgilePM, when is a Sprint-level exception considered to have arisen?', options: ['When the Delivery Team determines that the Sprint Goal is at risk \u2014 for example if agreed Must Haves will not be delivered', 'Whenever a Could Have is dropped', 'Whenever a Developer is absent for one day', 'Whenever the Daily Scrum lasts 16 minutes'], correct: 'When the Delivery Team determines that the Sprint Goal is at risk \u2014 for example if agreed Must Haves will not be delivered', explain: 'Not achieving the Sprint Goal is a major deviation; in AgilePM it is also escalated to the Project Manager (10.4.2).' },
      { id: 'P6Q44', topic: 'RK', q: 'PAQ Statement 4 says on-time delivery of an acceptable solution is the primary measure of success. What is the suggested action if there is no strict business deadline?', options: ['Still set a clear delivery target, otherwise the project may lose focus and become unmanageable', 'Leave the end date open so features can grow', 'Ask the estimator to pick a single figure', 'Cancel timeboxing and manage only cost'], correct: 'Still set a clear delivery target, otherwise the project may lose focus and become unmanageable', explain: 'Even without a hard deadline, a fixed end date (or increment date) keeps control (11.2.2.4).' },
      { id: 'P6Q45', topic: 'RK', q: 'Which of the following statements, about PAQ Statement 10 (empowerment), are true?\n1. If Delivery Team members constantly need Project Role approval, decisions slow and deadlines are put at risk\n2. If an organisation will not support team empowerment, it cannot fully adopt AgilePM', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Agile methods are incompatible with a strict top-down style; empowerment must be sufficient for Sprint-level decisions (11.2.2.10).' },
      { id: 'P6Q46', topic: 'RK', q: 'Delivery Enablement risk, owned by the Project Manager, includes which of the following?', options: ['Project organisation, schedule and internal and external dependencies', 'Solution architecture and the Definition of Done only', 'The Business Case and return on investment only', 'The ordering of the Product Backlog only'], correct: 'Project organisation, schedule and internal and external dependencies', explain: 'The Project Manager owns Delivery Enablement risk, including organisation, schedule and dependencies (11.1).' },
      { id: 'P6Q47', topic: 'GV', q: 'Appendix A distinguishes two types of Project Artifact. Which pairing is correct?', options: ['Evolutionary artifacts develop through the project; milestone artifacts are produced at a specific phase as a checkpoint', 'Milestone artifacts replace the need for a Business Case', 'Evolutionary artifacts are never updated after Feasibility', 'Only milestone artifacts may be used for governance'], correct: 'Evolutionary artifacts develop through the project; milestone artifacts are produced at a specific phase as a checkpoint', explain: 'Terms of Reference, Feasibility Assessment and Foundations Summary are milestone examples; Business Case and backlogs are evolutionary (App. A).' },
      { id: 'P6Q48', topic: 'GV', q: 'For the Terms of Reference, who is Responsible and who is Accountable?', options: ['Business Visionary is Responsible; Business Sponsor is Accountable', 'Project Manager is Responsible; Product Owner is Accountable', 'Solution Architect is Responsible; Scrum Master is Accountable', 'Developers are Responsible; Business Visionary is Accountable'], correct: 'Business Visionary is Responsible; Business Sponsor is Accountable', explain: 'ToR RACI: BV Responsible, BS Accountable (App. A).' },
      { id: 'P6Q49', topic: 'GV', q: 'Which of the following statements, about the Delivery Approach Definition (DAD), are true?\n1. The Solution Architect is Responsible for the DAD\n2. The Project Manager is Accountable for the DAD\n3. A major part of the DAD is the quality-assurance strategy\n4. The DAD is a required Feasibility artifact', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'DAD is optional; SA is Responsible, PM is Accountable; it includes the QA/testing strategy (App. A / 7.3).' },
      { id: 'P6Q50', topic: 'GV', q: 'For the Benefits Assessment, who is Responsible and who is Accountable?', options: ['Business Visionary is Responsible; Business Sponsor is Accountable', 'Project Manager is Responsible and Accountable', 'Product Owner is Responsible; Scrum Master is Accountable', 'Solution Architect is Responsible; Business Visionary is Accountable'], correct: 'Business Visionary is Responsible; Business Sponsor is Accountable', explain: 'Benefits Assessment RACI: BV Responsible, BS Accountable (App. A).' },
    ],
  },
  {
    id: 'hardG',
    title: 'Full Mock Exam 7',
    questions: [
      { id: 'P7Q1', topic: 'KC', q: 'Within the Framework for Business Agility (FBA), which segment does AgilePM address?', options: ['The \u2018change\u2019 segment \u2014 structured yet adaptive management of agile projects and product development', 'The \u2018culture\u2019 segment only', 'The \u2018operations\u2019 segment only', 'The entire FBA, replacing organisational agility'], correct: 'The \u2018change\u2019 segment \u2014 structured yet adaptive management of agile projects and product development', explain: 'The FBA is wider organisational agility; AgilePM sits in the change segment (Ch.1).' },
      { id: 'P7Q2', topic: 'KC', q: 'Identify the missing words. \u2018Boundaries of empowerment\u2019 describe how much [ ? ] someone has, and the limits of what they can decide without extra approval.', options: ['freedom to act', 'budget to spend', 'documentation to produce', 'overtime they may claim'], correct: 'freedom to act', explain: 'Boundaries of empowerment set authority/responsibility and the limit of unaided decisions (2.1.3).' },
      { id: 'P7Q3', topic: 'KC', q: 'Which of the following statements, about when Scrum is suited, are true?\n1. Scrum works best where work is complex and the solution is not fully known from the start\n2. Scrum is equally well suited to standardised, highly repetitive routine work such as manufacturing', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Scrum suits complex, collaborative work; it is less suited to routine, already well-defined tasks (2.3).' },
      { id: 'P7Q4', topic: 'KC', q: 'Which of the following should characterise agile documents?', options: ['Light-touch, guiding, visible to everyone involved, and clearly understood', 'Highly detailed, controlling, and restricted to the Project Manager', 'Written once in Pre-Project and never updated', 'Produced only after Deployment'], correct: 'Light-touch, guiding, visible to everyone involved, and clearly understood', explain: 'Heavy documents go stale in a VUCA world; agile documents guide rather than control (2.1.3).' },
      { id: 'P7Q5', topic: 'KC', q: 'Which of the following statements, about Product Lifecycle Management, are true?\n1. Feasibility is one of the named PLM stages\n2. PLM looks across the product\u2019s whole life, including distribution and servicing\n3. Retirement is part of the PLM view\n4. Project Feasibility is a lifecycle phase, not a PLM stage', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'PLM covers ideation/development, distribution, servicing and retirement; Feasibility is an AgilePM project phase (2.2).' },
      { id: 'P7Q6', topic: 'SC', q: 'Which sequence is the Scrum \u2018nutshell\u2019 described in the Guide?', options: ['Product Owner orders the backlog; the team turns selected work into an Increment; inspect and adjust; repeat', 'Write a full specification; build; test; hand over', 'Project Manager assigns tasks; Developers execute; Sponsor signs off', 'Feasibility; Foundations; Delivery; Deployment'], correct: 'Product Owner orders the backlog; the team turns selected work into an Increment; inspect and adjust; repeat', explain: 'The four-step Scrum nutshell is order, build an Increment, inspect/adjust, repeat (3.1).' },
      { id: 'P7Q7', topic: 'SC', q: 'During Topic Three of Sprint Planning, selected Product Backlog items are often decomposed into work items of what size?', options: ['One day or less', 'One week exactly', 'The full remaining Project Increment', 'Whatever the Project Manager dictates'], correct: 'One day or less', explain: 'Topic 3 (\u2018How\u2019) typically decomposes work to one day or less (3.5).' },
      { id: 'P7Q8', topic: 'SC', q: 'Which of the following statements, about a Product Backlog item that is not Done, are true?\n1. It cannot be released or even presented at the Sprint Review\n2. It returns to the Product Backlog for future consideration', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'If it misses the Definition of Done it is not presented and returns to the Product Backlog (3.6).' },
      { id: 'P7Q9', topic: 'SC', q: 'Which of the following may happen during a Sprint without endangering the Sprint Goal?\n1. Quality may be reduced to protect the date\n2. The Product Backlog may be refined as needed\n3. Scope may be clarified or renegotiated with the Product Owner\n4. No change that endangers the Sprint Goal is made', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Quality does not decrease; refinement and renegotiation with the Product Owner are allowed (3.5).' },
      { id: 'P7Q10', topic: 'SC', q: 'Which statement about the rhythm of Sprints is true?', options: ['Sprints are consecutive fixed-length events; the next one begins as soon as the previous one ends', 'A firebreak of at least one week is mandatory between Sprints', 'A Sprint may start only after the Business Sponsor signs the Increment', 'Sprints are scheduled only on the first Monday of each month'], correct: 'Sprints are consecutive fixed-length events; the next one begins as soon as the previous one ends', explain: 'A new Sprint starts immediately after the previous Sprint concludes (3.5).' },
      { id: 'P7Q11', topic: 'SC', q: 'Identify the missing word. The Sprint Goal is a single objective that provides [ ? ] in the exact work needed to achieve it.', options: ['flexibility', 'a fixed task list', 'a contractual penalty', 'a quality reduction'], correct: 'flexibility', explain: 'The Sprint Goal is a commitment that still allows flexibility in the exact work (3.6).' },
      { id: 'P7Q12', topic: 'AF', q: 'Which of the following are recognised problems with using time or budget as contingency in traditional project management?\n1. Sponsors hesitate to set formal contingency aside (Parkinson\u2019s Law)\n2. Approving changes is complex and time-consuming\n3. Once planned contingency runs out, control of the variables becomes difficult\n4. Quality is protected automatically if extra time is added', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Those three issues are why AgilePM puts contingency in features via MoSCoW (4.2).' },
      { id: 'P7Q13', topic: 'AF', q: 'Under \u2018Never Compromise Quality\u2019, when should the expected quality level be defined, and what does \u2018fit-for-purpose\u2019 mean?', options: ['At the beginning; \u2018good enough\u2019 to meet business needs \u2014 neither exceeding nor falling short', 'At Deployment; as technically excellent as budget allows', 'At each Daily Scrum; zero defects of any kind', 'Only if a regulator requests it; whatever the Developers prefer'], correct: 'At the beginning; \u2018good enough\u2019 to meet business needs \u2014 neither exceeding nor falling short', explain: 'Quality is agreed up front via the Definition of Done; gold-plating is not required (4.3).' },
      { id: 'P7Q14', topic: 'AF', q: 'Which of the following statements, about reports and control, are true?\n1. Reports can be outdated and miss details that are visible in the actual work\n2. High-level plans, designs and standards must still define what needs to be done, how, and when', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Demonstrate Control uses transparency of real work; reports are not the primary governance source (4.3).' },
      { id: 'P7Q15', topic: 'AF', q: 'Which of the following is NOT one of the five AgilePM practices that enable the principles?', options: ['Pair programming', 'Iterative development', 'Modelling', 'Facilitated workshops'], correct: 'Pair programming', explain: 'The five are Iterative Development, Timeboxing, MoSCoW, Modelling and Facilitated Workshops (4.3).' },
      { id: 'P7Q16', topic: 'AF', q: 'Identify the missing words. The Project Manager does not create the Business Case, but must ensure it [ ? ] throughout the project.', options: ['receives appropriate attention', 'is rewritten every Daily Scrum', 'is owned by the Scrum Master', 'is replaced by the Sprint Backlog'], correct: 'receives appropriate attention', explain: 'Value Ownership roles own the Business Case; the Project Manager keeps attention on it (4.3).' },
      { id: 'P7Q17', topic: 'IN', q: 'Which of the following are the three AgilePM role categories?', options: ['Project, Delivery Team and Advisor', 'Sponsor, Auditor and Supplier', 'Scrum Master, Developer and Regulator', 'Portfolio, Programme and Project'], correct: 'Project, Delivery Team and Advisor', explain: 'Project roles (outer), Delivery Team (inner) and Advisor (outside) (5.2).' },
      { id: 'P7Q18', topic: 'IN', q: 'Which of the following statements, about the Business Visionary, are true?\n1. They may delegate Product Backlog work but remain accountable\n2. Those wanting to change the Solution Backlog must convince the Business Visionary there is better value in the change', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'The Business Visionary owns the evolving solution/Solution Backlog and remains accountable if they delegate (5.3.2).' },
      { id: 'P7Q19', topic: 'IN', q: 'In some organisational contexts, value-ownership accountabilities at team level may be fulfilled by which role instead of a Product Owner?', options: ['Business Ambassador', 'Process Advisor', 'External auditor', 'Investment board'], correct: 'Business Ambassador', explain: 'The book notes a Business Ambassador may fulfil value ownership; backlog changes still go through that person (5.3.5).' },
      { id: 'P7Q20', topic: 'IN', q: 'Over what period is the Project Manager typically involved?', options: ['From the start of the project until the final deployment of the solution', 'Only during Feasibility', 'Only at the Sprint Retrospective', 'Only after Realisation begins'], correct: 'From the start of the project until the final deployment of the solution', explain: 'The Project Manager provides continuity and leadership through to final deployment (5.3.4).' },
      { id: 'P7Q21', topic: 'IN', q: 'Which of the following are Solution Architect accountabilities?\n1. Owning the solution architecture and delivery approach\n2. Ensuring regulatory or quality standards are reflected in the Definition of Done\n3. Holding the project budget\n4. Providing guidance across Delivery Teams so the solution stays coherent', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The budget is the Business Sponsor\u2019s; the Solution Architect owns design, DoD quality/compliance and cross-team coherence (5.3.3).' },
      { id: 'P7Q22', topic: 'IN', q: 'Who owns and responds to stakeholder-related issues and risks, with the Project Manager supporting engagement?', options: ['The Project Manager and the Product Owner', 'The Scrum Master alone', 'The Developers alone', 'External regulators alone'], correct: 'The Project Manager and the Product Owner', explain: 'The Project Manager and Product Owner are accountable for stakeholder issues/risks; the PM supports timely communication (5.5).' },
      { id: 'P7Q23', topic: 'IN', q: 'Identify the missing words. External stakeholders can include people [ ? ], such as employees affected by a business change, as well as customers, suppliers or regulators.', options: ['internal to the organisation', 'only outside the legal entity', 'only if they fund the project', 'only if they attend every Sprint Review'], correct: 'internal to the organisation', explain: 'External to the project does not mean external to the organisation (5.2).' },
      { id: 'P7Q24', topic: 'CC', q: 'What is the difference between team collaboration and community collaboration?', options: ['Team collaboration is a group sharing responsibility for one goal; community collaboration creates unity across teams and organisational boundaries', 'Team collaboration is written only; community collaboration is face-to-face only', 'They are identical terms', 'Community collaboration replaces the need for a Product Owner'], correct: 'Team collaboration is a group sharing responsibility for one goal; community collaboration creates unity across teams and organisational boundaries', explain: 'Both are needed; community collaboration relies on the nine leadership principles and agreements (6.2).' },
      { id: 'P7Q25', topic: 'CC', q: 'Which of the following statements, about hiring and communication skill, are true?\n1. A team that communicates well will accomplish more than one that relies only on technical ability\n2. Communication skill should be ignored when selecting specialists', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Consider technical expertise and interpersonal skill together (6.3).' },
      { id: 'P7Q26', topic: 'CC', q: 'Which of the following are forms that modelling may take?\n1. A way to describe something not visible, making it easier to understand\n2. A detailed scaled-down version of a real object or system\n3. A legally binding substitute for the Business Case\n4. A pattern or figure used to create a final product', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Modelling is a visual representation \u2014 not a substitute for the Business Case (6.4).' },
      { id: 'P7Q27', topic: 'CC', q: 'On the Power/Interest grid, how should a stakeholder with low power and high interest be treated?', options: ['Keep informed', 'Closely engage', 'Keep satisfied', 'Monitor with minimum effort'], correct: 'Keep informed', explain: 'Low power / high interest = keep informed (Fig. 6.2).' },
      { id: 'P7Q28', topic: 'PR', q: 'Which of the following statements, about Pre-Project, are true?\n1. Its purpose is to decide whether it is worth exploring further and when it should start \u2014 not to evaluate feasibility in detail\n2. In larger organisations it may require a written proposal for an investment committee as part of portfolio or programme governance', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Pre-Project seeks a small investment to investigate; feasibility comes later (7.2\u20137.3).' },
      { id: 'P7Q29', topic: 'PR', q: 'What three things does Feasibility examine?', options: ['Solution feasibility, stakeholder desirability/viability, and people\u2019s capability to work in an agile way', 'Only the final production schedule', 'Only the Sprint Backlog', 'Only regulatory certificates'], correct: 'Solution feasibility, stakeholder desirability/viability, and people\u2019s capability to work in an agile way', explain: 'Can it be built, will it deliver value cost-effectively, and is the culture/leadership capable? (7.3).' },
      { id: 'P7Q30', topic: 'PR', q: 'After the project completes, how may the Deployed Solution continue to evolve?\n1. By freezing the solution permanently with no further work\n2. Continuous improvement in a product-management context with a small funded agile team\n3. A future project for major change\n4. A future client project delivering an instance of the solution', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'The book lists continuous improvement, a future project, or a future client project (7.2).' },
      { id: 'P7Q31', topic: 'PR', q: 'Identify the missing words. AgilePM also accepts that some teams use [ ? ] \u2014 a continuous flow of work instead of timeboxed Sprints.', options: ['Kanban', 'a Gantt baseline', 'scientific management', 'fixed-scope contracting'], correct: 'Kanban', explain: 'Sprints are the default model; Kanban-style continuous flow is also accepted (7.5).' },
      { id: 'P7Q32', topic: 'PR', q: 'What are the three key purposes of the Delivery Plan?', options: ['Communicate expectations, act as a baseline for tracking/governance, and outline work to bring the solution into live operation', 'Replace the Business Case, cancel MoSCoW, and fix features', 'Record individual appraisals, set salaries, and assign blame', 'List only Won\u2019t Have requirements'], correct: 'Communicate expectations, act as a baseline for tracking/governance, and outline work to bring the solution into live operation', explain: 'Those three purposes are stated for the Delivery Plan (7.4).' },
      { id: 'P7Q33', topic: 'ES', q: 'Who popularised User Stories through the book User Stories Applied, and who invented Story Mapping?', options: ['Mike Cohn popularised User Stories; Jeff Patton invented Story Mapping', 'Dan North popularised User Stories; Bill Wake invented Story Mapping', 'Rachel Davies popularised both', 'Ken Schwaber invented both'], correct: 'Mike Cohn popularised User Stories; Jeff Patton invented Story Mapping', explain: 'User Stories originated in XP; Cohn popularised them; Patton created Story Mapping; Davies created the As a/I want/so that format (8.2.3).' },
      { id: 'P7Q34', topic: 'ES', q: 'Which of the following statements, about the Definition of Ready, are true?\n1. The Scrum Guide hints that items should be \u2018ready\u2019 but does not define the criteria\n2. INVEST is a useful basis for a team\u2019s Definition of Ready when User Stories are used', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Teams define their own DoR; INVEST overlaps with typical ready criteria (8.2.3.5).' },
      { id: 'P7Q35', topic: 'ES', q: 'What is the relationship between Acceptance Criteria and the Definition of Done?', options: ['Meeting Acceptance Criteria is usually one criterion within the Definition of Done, not a substitute for it', 'They are identical and interchangeable terms', 'Acceptance Criteria replace the Definition of Done at project level', 'The Definition of Done is written only as Given/When/Then'], correct: 'Meeting Acceptance Criteria is usually one criterion within the Definition of Done, not a substitute for it', explain: 'Acceptance Criteria confirm a story; the Definition of Done is the wider quality bar for the Increment (8.2.3.7).' },
      { id: 'P7Q36', topic: 'ES', q: 'During Feasibility, estimates are commonly expressed how?', options: ['As time ranges (for example 100\u2013200 team days or 3\u20136 months) and cost/benefit ranges, often using T-shirt sizing', 'As exact story points that will never change', 'As a single figure chosen by the estimator', 'As hours booked on a timesheet only'], correct: 'As time ranges (for example 100\u2013200 team days or 3\u20136 months) and cost/benefit ranges, often using T-shirt sizing', explain: 'Early estimates use analogy/time, not precise story points (8.3.5.1).' },
      { id: 'P7Q37', topic: 'ES', q: 'Which of the following are true of velocity?\n1. It is unique to each team and cannot be compared across teams\n2. Changes in team composition mean velocity must be re-established\n3. It is a measure of outcome value, not output\n4. It is a useful input to Sprint Planning Topic 2', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Velocity measures output (story points Done), not outcomes, and is team-specific (8.3.3.2).' },
      { id: 'P7Q38', topic: 'ES', q: 'If a project is high risk (new technology or an inexperienced team), what does AgilePM suggest about Must Have effort?', options: ['It may be wise to reduce Must Have effort below the usual 60% guidance', 'Increase Must Haves to 80% to force delivery', 'Ignore MoSCoW and fix features instead', 'Move all Must Haves to Won\u2019t Have'], correct: 'It may be wise to reduce Must Have effort below the usual 60% guidance', explain: '60/20/20 is guidance, not a hard rule; higher risk means more contingency (9.5).' },
      { id: 'P7Q39', topic: 'PC', q: 'By the end of Foundations, high-level requirements from Feasibility have usually been expanded to what sort of number?', options: ['Tens of requirements, probably fewer than 100', 'Exactly three Epic stories', 'Several thousand task-level requirements', 'No requirements until Sprint 1'], correct: 'Tens of requirements, probably fewer than 100', explain: 'Foundations expands Feasibility Epics into more detailed but still high-level stories, typically tens and probably <100 (10.2.3.3).' },
      { id: 'P7Q40', topic: 'PC', q: 'Which of the following statements, about deploying during a Sprint, are true?\n1. Deploying a Done Product Increment during a Sprint is acceptable if it aligns with the Delivery Plan and will not harm other teams\n2. Such deployments should be planned in Sprint Planning, not performed unilaterally', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Continuous delivery is allowed when planned and non-disruptive (10.2.3.6.3).' },
      { id: 'P7Q41', topic: 'PC', q: 'Burn-down, burn-up and cumulative flow charts should NOT be used for which purpose?', options: ['Judging or comparing team performance', 'Inspecting progress toward the Sprint Goal', 'Making work transparent', 'Deciding whether adaptation is needed'], correct: 'Judging or comparing team performance', explain: 'Charts are working tools for empiricism, not performance appraisal (10.2.3.5).' },
      { id: 'P7Q42', topic: 'PC', q: 'Who is accountable for the wider business changes that come with implementing the solution and for subsequent benefits realisation?', options: ['Business Visionary', 'Scrum Master', 'Developers', 'Process Advisor'], correct: 'Business Visionary', explain: 'The Business Visionary is accountable for business change and benefits realisation planning (10.2.3.10).' },
      { id: 'P7Q43', topic: 'PC', q: 'Which of the following should be agreed during Foundations because the distinction can otherwise become subjective?\n1. How Should Have differs from Could Have in this project\n2. Criteria such as number of people impacted or effort-versus-benefit that raise a Could Have to a Should Have\n3. That the Project Manager will personally assign every MoSCoW priority\n4. That Must Haves remain non-negotiable', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The Project Manager does not assign priorities; the organisation agrees how lesser priorities will be applied (10.3 / 9.8).' },
      { id: 'P7Q44', topic: 'RK', q: 'If PAQ Statement 1 (everyone understands and accepts AgilePM and Scrum) is disagreed, what is the usual first remedy?', options: ['Provide training for those actively involved and briefings for those less involved; use accredited trainers or coaches if needed', 'Replace AgilePM with a sequential method immediately', 'Ask the Developers to write a new manifesto', 'Ignore the disagreement if the Project Manager understands the method'], correct: 'Provide training for those actively involved and briefings for those less involved; use accredited trainers or coaches if needed', explain: 'Disagreement usually means missing training/briefing; a powerful opponent is a separate, rarer problem (11.2.2.1).' },
      { id: 'P7Q45', topic: 'RK', q: 'Which of the following statements, about part-time Delivery Team members (PAQ Statement 13), are true?\n1. Developers are generally expected to work full-time, at least for a Project Increment\n2. If availability is a problem, AgilePM recommends extending Sprint length to compensate', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Do not extend Sprints \u2014 that reduces focus; plan around availability or discuss staffing with the Business Sponsor (11.2.2.13).' },
      { id: 'P7Q46', topic: 'RK', q: 'Identify the missing words. PAQ Statement 17 groups constraints into internal standards, external (regulatory) standards and [ ? ].', options: ['commercial arrangements', 'team hobbies', 'office floor plans', 'marketing slogans'], correct: 'commercial arrangements', explain: 'The three constraint types are internal standards, external/regulatory standards and commercial arrangements (11.2.2.17).' },
      { id: 'P7Q47', topic: 'GV', q: 'For the Solution Architecture Definition, who is Responsible and who is Accountable?', options: ['Solution Architect is Responsible; Business Visionary is Accountable', 'Project Manager is Responsible; Business Sponsor is Accountable', 'Product Owner is Responsible; Scrum Master is Accountable', 'Developers are Responsible; Project Manager is Accountable'], correct: 'Solution Architect is Responsible; Business Visionary is Accountable', explain: 'SAD RACI: SA Responsible, BV Accountable (App. A).' },
      { id: 'P7Q48', topic: 'GV', q: 'Which of the following statements, about auditors and agile evidence, are true?\n1. A standard may require traceability without specifying that it must be a traditional specification\n2. An auditor might not recognise a User Story or Sprint Backlog as a valid plan unless it is explained', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Understand the regulation\u2019s intent, then meet it in an agile way and help auditors see valid evidence (12.2).' },
      { id: 'P7Q49', topic: 'GV', q: 'Which of the following are milestone Project Artifacts?\n1. Terms of Reference\n2. Feasibility Assessment\n3. Product Backlog\n4. Foundations Summary', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'ToR, Feasibility Assessment and Foundations Summary are milestone artifacts; the Product Backlog is evolutionary (App. A).' },
      { id: 'P7Q50', topic: 'GV', q: 'When is the Business Case formally reviewed to check whether it is still sensible to continue?', options: ['At the end of each Project Increment', 'Only once, in Pre-Project', 'At every Daily Scrum', 'Never \u2014 it is frozen after Feasibility'], correct: 'At the end of each Project Increment', explain: 'Drafted by end of Feasibility, fuller by end of Foundations, formally reviewed at each increment (App. A).' },
    ],
  },
  {
    id: 'hardH',
    title: 'Full Mock Exam 8',
    questions: [
      { id: 'P8Q1', topic: 'KC', q: 'Why was DSDM launched in 1994, and what blend of earlier approaches did it take?', options: ['To fix Waterfall (too slow, too little ongoing business involvement) and RAD (speed over quality); it kept Waterfall control/quality and RAD iteration/transparency', 'To replace the Agile Manifesto before it existed', 'To standardise Scientific Management for software factories', 'To remove all quality controls from RAD'], correct: 'To fix Waterfall (too slow, too little ongoing business involvement) and RAD (speed over quality); it kept Waterfall control/quality and RAD iteration/transparency', explain: 'DSDM combined the best of Waterfall and RAD and later evolved into AgilePM (Ch.1).' },
      { id: 'P8Q2', topic: 'KC', q: 'Identify the missing words. Empowerment requires people to be capable, willing and [ ? ].', options: ['informed', 'senior', 'certified', 'silent'], correct: 'informed', explain: 'Capable (skills), willing (ready to take responsibility) and informed (enough data) (2.1.3).' },
      { id: 'P8Q3', topic: 'KC', q: 'Which of the following statements, about project management versus product development, are true?\n1. Project management organises the environment and the Who/Why/When/Where so value is actually achieved once delivered\n2. Product development focuses mainly on what the product is and how it is designed, built and improved', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'PM takes the wider view; product development focuses on the what and how (2.2\u20132.3).' },
      { id: 'P8Q4', topic: 'KC', q: 'Why is agility still valuable on a relatively stable project?', options: ['It improves communication and stakeholder involvement and allows incremental benefits at no extra risk', 'It guarantees a fixed scope', 'It removes all documentation', 'It eliminates the need for a Business Sponsor'], correct: 'It improves communication and stakeholder involvement and allows incremental benefits at no extra risk', explain: 'Agile practices add value even when the environment is stable (2.4.3).' },
      { id: 'P8Q5', topic: 'KC', q: 'Which of the following are Agile Manifesto principles (ABC-enhanced)?\n1. Complete the detailed design before any collaboration begins\n2. Working solutions are the primary measure of progress\n3. Simplicity \u2014 maximising the amount of work not done\n4. Best outcomes emerge from self-organising teams', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Principles 7, 10 and 11; detailed design up front contradicts last-responsible-moment thinking (2.1.4).' },
      { id: 'P8Q6', topic: 'SC', q: 'Identify the missing words. Transparency without inspection is [ ? ]; inspection without adaptation is [ ? ].', options: ['misleading and wasteful; pointless', 'optional; mandatory', 'the same as adaptation; the same as transparency', 'a Scrum Master duty; a sponsor duty'], correct: 'misleading and wasteful; pointless', explain: 'The pillars are sequential: transparency enables inspection, inspection enables adaptation (3.2).' },
      { id: 'P8Q7', topic: 'SC', q: 'Which statement about the Product Backlog as a Scrum artifact is true?', options: ['It is emergent and ordered, and it is the single source of work undertaken by the Scrum Team', 'It is a fixed Pre-Project contract of every feature', 'It is the Project Manager\u2019s personal task list', 'It records hours booked against the Business Case'], correct: 'It is emergent and ordered, and it is the single source of work undertaken by the Scrum Team', explain: 'The Product Backlog is the single source of work and evolves as understanding grows (3.6).' },
      { id: 'P8Q8', topic: 'SC', q: 'Which of the following statements, about the Sprint Retrospective, are true?\n1. The Scrum Team inspects individuals, interactions, processes, tools and the Definition of Done\n2. Its purpose is to demonstrate the Increment to external stakeholders', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'The Review inspects the Increment with stakeholders; the Retrospective improves quality and effectiveness (3.5).' },
      { id: 'P8Q9', topic: 'SC', q: 'Which of the following are rules that apply during a Sprint?\n1. The Sprint is cancelled automatically if any Could Have is dropped\n2. No changes that would endanger the Sprint Goal\n3. Quality does not decrease\n4. Scope may be clarified or renegotiated with the Product Owner as more is learned', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Dropping a Could Have is normal MoSCoW contingency, not a reason to cancel the Sprint (3.5).' },
      { id: 'P8Q10', topic: 'SC', q: 'Who created Scrum?', options: ['Ken Schwaber and Jeff Sutherland', 'James Martin and Arie van Bennekum', 'Barry Boehm and Jim Highsmith', 'Rachel Davies and Dan North'], correct: 'Ken Schwaber and Jeff Sutherland', explain: 'Schwaber and Sutherland created Scrum and described it as lightweight, simple to understand and difficult to master (2.4 / 3.1).' },
      { id: 'P8Q11', topic: 'SC', q: 'What does Product Backlog refinement add to items?', options: ['Details such as description, order and size', 'The project budget', 'The Business Case vision statement', 'A legally binding delivery date'], correct: 'Details such as description, order and size', explain: 'Refinement is the ongoing act of breaking down and further defining items (3.6).' },
      { id: 'P8Q12', topic: 'AF', q: 'Which four conditions does the AgilePM philosophy require of every stakeholder?', options: ['They understand the vision, are empowered in their expertise, collaborate to create and deliver on time, and accept that change will be required', 'They have signed a fixed-scope contract, work alone, reject change, and report only in writing', 'They attend every Daily Scrum, own the budget, set the Definition of Done, and cancel Sprints', 'They produce a full specification, freeze features, vary quality, and avoid collaboration'], correct: 'They understand the vision, are empowered in their expertise, collaborate to create and deliver on time, and accept that change will be required', explain: 'These conditions sit under the philosophy of clear goals, frequent delivery and empowered people (4.1).' },
      { id: 'P8Q13', topic: 'AF', q: 'Which of the following statements, about \u2018Build Incrementally from Firm Foundations\u2019, are true?\n1. Teams should gain a high-level understanding of the business problem, the proposed solution and associated risk before major development\n2. The Business Visionary, Solution Architect and Project Manager lead the building of those foundations', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'BV (value), SA (solution) and PM (delivery enablement) establish foundations before major build (4.3).' },
      { id: 'P8Q14', topic: 'AF', q: 'What three things must the Project Manager do to support the Collaborate principle?', options: ['Ensure the right stakeholders are involved at the right time, encourage business-representative participation, and ensure people are empowered to decide', 'Write every User Story, set the Definition of Done, and own the budget', 'Cancel collaboration if it slows reporting', 'Replace workshops with email only'], correct: 'Ensure the right stakeholders are involved at the right time, encourage business-representative participation, and ensure people are empowered to decide', explain: 'Those three PM actions support a one-team culture (4.3).' },
      { id: 'P8Q15', topic: 'AF', q: 'The four iterative cycles of \u2018Develop Iteratively\u2019 are described as providing which of the following?\n1. Transparency through frequent demonstrations\n2. Inspection through regular reviews\n3. Adaptation based on feedback\n4. A freeze on all change after Foundations', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The fourth idea is evolution \u2014 change is embraced, not frozen (4.3).' },
      { id: 'P8Q16', topic: 'AF', q: 'Identify the missing words. Artificial deadlines that do not align with real business needs can be harmful if used only as a [ ? ].', options: ['measure of success or control', 'MoSCoW priority', 'Definition of Done criterion', 'Sprint Goal'], correct: 'measure of success or control', explain: 'Artificial deadlines used only as control can damage the project (4.3).' },
      { id: 'P8Q17', topic: 'IN', q: 'From a Scrum perspective, which role is the team-level Value Ownership role, and which two AgilePM project roles occupy that domain?', options: ['Product Owner; Business Sponsor and Business Visionary', 'Scrum Master; Project Manager and Solution Architect', 'Developer; Process Advisor and Business Ambassador', 'Business Advisor; Scrum Master and Team Leader'], correct: 'Product Owner; Business Sponsor and Business Visionary', explain: 'Value Ownership is BS/BV at project level; the Product Owner is the Scrum/team-level value role (5.2).' },
      { id: 'P8Q18', topic: 'IN', q: 'Which of the following statements, about decision rights, are true?\n1. The Business Visionary makes business-value-related decisions\n2. The Solution Architect makes decisions about the integrity and delivery of the solution\n3. The Project Manager makes decisions about how the project is managed\n4. The three leadership roles plus the Project Manager all share identical authority', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Equal authority sits with BS, BV and SA; the PM is empowered to lead delivery but is not in that equal-authority trio (5.3).' },
      { id: 'P8Q19', topic: 'IN', q: 'In a mature Scrum / product-management context, a single person may combine Business Sponsor, Business Visionary and which other role?', options: ['Product Owner', 'Scrum Master', 'External regulator', 'Investment-board chair only'], correct: 'Product Owner', explain: 'In that context the singular role behaves more like a Product Owner in a mature Scrum Team (5.3).' },
      { id: 'P8Q20', topic: 'IN', q: 'Why does Scrum use the word \u2018Developers\u2019 for everyone working on the Sprint Backlog?', options: ['Not to exclude, but to simplify \u2014 the team is intentionally cross-functional with different skills', 'Because only software programmers are allowed', 'Because testers and designers sit outside the team', 'Because the Project Manager assigns that title'], correct: 'Not to exclude, but to simplify \u2014 the team is intentionally cross-functional with different skills', explain: 'The title suggests uniformity, but the opposite is intended (5.4).' },
      { id: 'P8Q21', topic: 'IN', q: 'Which of the following statements, about Geoff Watts\u2019 commandment \u2018First ask the team\u2019, are true?\n1. Default to asking the team because they have knowledge and context\n2. Jumping in with the Scrum Master\u2019s own answer can undermine team members', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Resist solving it for them; encourage the team to discuss real and hypothetical situations (5.3.6).' },
      { id: 'P8Q22', topic: 'IN', q: 'A person who helps shape the project in Feasibility as a Business Advisor may later become which role?', options: ['Product Owner or Business Ambassador', 'Business Sponsor only', 'External regulator only', 'Investment-board member only'], correct: 'Product Owner or Business Ambassador', explain: 'Advisor roles may later join the Delivery Team as PO/Ambassador (business), Developer (solution) (5.2).' },
      { id: 'P8Q23', topic: 'IN', q: 'Identify the missing words. If a stakeholder\u2019s needs change, the Project Manager should arrange conversations to review priorities and update the [ ? ] if needed.', options: ['project plan', 'Definition of Done', 'Agile Manifesto', 'PAQ scoring scale'], correct: 'project plan', explain: 'The PM balances stakeholder expectations, project goals and agile working (5.5).' },
      { id: 'P8Q24', topic: 'CC', q: 'Which of the following is a soft skill AgilePM lists as needed for collaboration?', options: ['Empathy', 'Gantt-chart authorship', 'Sole ownership of the budget', 'Withholding information'], correct: 'Empathy', explain: 'Soft skills include creativity, empathy, problem-solving, adaptability, reliability, resilience, leadership, teamwork and communication (6.1).' },
      { id: 'P8Q25', topic: 'CC', q: 'Which of the following statements, about over-using technology, are true?\n1. Replacing face-to-face discussion with email or messaging can cause misunderstanding because body language and tone are missing\n2. Virtual meetings are usually richer if video is used rather than audio only', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Technology can help but over-use reduces effectiveness; prefer video over audio (6.3).' },
      { id: 'P8Q26', topic: 'CC', q: 'A facilitated workshop requires which three elements?', options: ['An owner with a clear outcome, selected participants with knowledge and authority, and an independent facilitator', 'Only a Project Manager and a slide deck', 'A signed fixed-scope contract and a regulator', 'The entire organisation and no agenda'], correct: 'An owner with a clear outcome, selected participants with knowledge and authority, and an independent facilitator', explain: 'The facilitator is a Process Advisor role and keeps the workshop neutral (6.4).' },
      { id: 'P8Q27', topic: 'CC', q: 'Which of the following are the six communication choices listed by AgilePM?\n1. Face-to-face and virtual meetings\n2. Instant messaging and social media\n3. Annual appraisals and disciplinary hearings\n4. Email and collaborative workspaces', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The six are face-to-face, virtual meetings, instant messaging, social media, email and collaborative workspaces (6.3).' },
      { id: 'P8Q28', topic: 'PR', q: 'What is a Project Increment Timebox bounded by at each end?', options: ['A revisit of Foundations at the start and a Project Increment Review at the end', 'Sprint Planning only', 'The Daily Scrum only', 'A Benefits Assessment only'], correct: 'A revisit of Foundations at the start and a Project Increment Review at the end', explain: 'Those two events bound the increment timebox (7.1).' },
      { id: 'P8Q29', topic: 'PR', q: 'Which of the following statements, about Example 4 in the lifecycle configurations, are true?\n1. Product/Solution Increments may be deployed multiple times each Sprint\n2. There is no return to Foundations; planning of the next increment is ongoing via Cross-Team Refinement and Project Sprint Reviews', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Example 4 is continuous delivery without a Foundations firebreak (Fig. 7.7).' },
      { id: 'P8Q30', topic: 'PR', q: 'The Foundations Summary can be developed in which two ways?', options: ['As a management summary of Business Case, SAD, DAD and MAD, or by combining those artifacts into one document', 'As a replacement for the Sprint Backlog, or as a timesheet', 'As the PAQ, or as the Team Board', 'As a contract, or as a disciplinary record'], correct: 'As a management summary of Business Case, SAD, DAD and MAD, or by combining those artifacts into one document', explain: 'Either form helps governance decide direction and viability (7.4).' },
      { id: 'P8Q31', topic: 'PR', q: 'Identify the missing words. Every project should go through the same lifecycle phases, but the [ ? ] required in each phase depends on the organisation and the project.', options: ['level of effort and formality', 'number of Must Haves', 'length of the Daily Scrum', 'name of the Scrum Master'], correct: 'level of effort and formality', explain: 'Phases are consistent; depth and formality are tailored (7.2).' },
      { id: 'P8Q32', topic: 'PR', q: 'Which of the following are true of the Feasibility Assessment?\n1. It is an optional milestone artifact\n2. It can act as a management summary of the Business Case, SAD, DAD and MAD\n3. It can replace those artifacts by combining their key details\n4. It is produced in the Realisation phase only', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The Feasibility Assessment is a snapshot at the end of Feasibility for a go/no-go decision (7.3 / App. A).' },
      { id: 'P8Q33', topic: 'ES', q: 'In INVEST, what does \u2018Small (Enough)\u2019 mean in AgilePM terms?', options: ['Manageable within a specific timebox \u2014 project, Project Increment or Sprint', 'Small enough to fit on one sticky note and nothing else', 'Smaller than one hour of work', 'Small enough that it needs no Acceptance Criteria'], correct: 'Manageable within a specific timebox \u2014 project, Project Increment or Sprint', explain: 'Bill Wake\u2019s Small means sized to the relevant timebox (8.2.3.4).' },
      { id: 'P8Q34', topic: 'ES', q: 'A useful tip for assigning MoSCoW priorities is to start where, and promote only with strong justification?', options: ['Start with all requirements as Won\u2019t Haves', 'Start with all requirements as Must Haves', 'Start with no written requirements', 'Start by letting the Project Manager assign every priority'], correct: 'Start with all requirements as Won\u2019t Haves', explain: 'Default to Won\u2019t Have and promote only when justified; also ask whether the project would be cancelled without it (9.8.1).' },
      { id: 'P8Q35', topic: 'ES', q: 'Which of the following statements, about estimating, are true?\n1. The most useful estimates come from the people who will do the work\n2. Overly detailed estimates too early can be misleading\n3. Decomposition always removes uncertainty\n4. Estimates should be continuously revalidated', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Decomposition does not necessarily reduce uncertainty; use it with analogy and keep revalidating (8.3).' },
      { id: 'P8Q36', topic: 'ES', q: 'Using the house-building illustration, why might foundations be Must Have in the first increment while the roof is only Should Have at that point?', options: ['A requirement\u2019s MoSCoW priority can differ at project, increment and Sprint levels', 'The roof is never needed in an AgilePM project', 'MoSCoW can only be applied once, at project level', 'Foundations are always a Could Have'], correct: 'A requirement\u2019s MoSCoW priority can differ at project, increment and Sprint levels', explain: 'The finished house needs a roof, but increment 1 may only need foundations as Must Have (9.3).' },
      { id: 'P8Q37', topic: 'ES', q: 'Fine-grained User Stories used in Delivery are typically of what effort, and when are they created?', options: ['Often 1\u20133 days of effort, refined during backlog refinement or Sprint Planning', 'Exactly 8 hours, written in Pre-Project', 'A full Project Increment each', 'No estimate is ever allowed'], correct: 'Often 1\u20133 days of effort, refined during backlog refinement or Sprint Planning', explain: 'Epics \u2192 User Stories (Foundations) \u2192 fine-grained items that fit a Sprint (8.2.3).' },
      { id: 'P8Q38', topic: 'ES', q: 'If a workaround exists for a requirement, how should its MoSCoW priority usually be treated?', options: ['It is not a Must Have; compare workaround cost with delivery cost to choose Should or Could', 'It must be classified as Must Have', 'It must be deleted from the backlog', 'It becomes a Won\u2019t Have automatically'], correct: 'It is not a Must Have; compare workaround cost with delivery cost to choose Should or Could', explain: 'A workaround test is one of the tips for assigning priorities (9.8.1).' },
      { id: 'P8Q39', topic: 'PC', q: 'Which planning horizon focuses on the first or next Project Increment, typically aligned to the Solution Goal and Product Goal?', options: ['Medium-term planning', 'Long-term planning covering the entire project and post-project', 'Short-term Sprint Planning only', 'Portfolio planning only'], correct: 'Medium-term planning', explain: 'Long = whole project + post-project; medium = increment; short = Sprint (10.2.2.2).' },
      { id: 'P8Q40', topic: 'PC', q: 'Which of the following statements, about Project Sprint Planning, are true?\n1. It mirrors the first two topics of standard Sprint Planning and is facilitated by the Project Manager\n2. Delivery Team Sprint Planning then focuses on Topic 3 \u2014 how the chosen work will get done', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Project-level planning aligns why/what; each team then plans how and produces its Sprint Backlog (10.2.3.4).' },
      { id: 'P8Q41', topic: 'PC', q: 'When new requirements are introduced at a Foundations revisit, what must not be increased?', options: ['The percentage of effort assigned to Must Have requirements', 'The number of Should Haves used as contingency', 'The use of Cross-Team Refinement', 'Transparency of the Delivery Plan'], correct: 'The percentage of effort assigned to Must Have requirements', explain: 'Adding too many Must Haves erodes contingency and puts dates at risk (10.2.3.11).' },
      { id: 'P8Q42', topic: 'PC', q: 'Deployment planning should include which of the following?\n1. A rollback option so the previous version can be restored if major problems arise\n2. A Plan B if rollback is not possible\n3. Booking facilities, training and technology resources in advance\n4. Unilateral go-live by one Delivery Team with no Delivery Plan alignment', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Rollback, Plan B and advance resourcing are required; deployment must not be unilateral (10.2.3.9).' },
      { id: 'P8Q43', topic: 'PC', q: 'Identify the missing words. Each Increment is an output; the outcome is only realised when the product or solution is [ ? ].', options: ['used in real-world operation', 'described in a status report', 'estimated in story points', 'approved as a Gantt baseline'], correct: 'used in real-world operation', explain: 'Outcome-based measurement tracks value realised, not merely outputs produced (10.4.1).' },
      { id: 'P8Q44', topic: 'RK', q: 'A high-level Must Have such as \u2018manage an appointment diary\u2019 is broken down into making an appointment (Must), cancelling (Should) and changing (Should). What point is PAQ Statement 5 making?', options: ['Even a Must Have epic can reveal contingency once it is decomposed', 'Every sub-requirement must remain a Must Have', 'MoSCoW can only be applied to the epic, never to the parts', 'Cancelling an appointment is always a Won\u2019t Have'], correct: 'Even a Must Have epic can reveal contingency once it is decomposed', explain: 'Detail emerging later often creates Should/Could flexibility inside a Must Have (11.2.2.5).' },
      { id: 'P8Q45', topic: 'RK', q: 'Which of the following statements, about a separate formal risk process, are true?\n1. Day-to-day AgilePM activities usually remove the need for a separate heavyweight risk process\n2. Highly regulated or safety-related contexts may still require an intentional risk process, reflected in MAD, SAD and DAD', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Risk is integrated; extra process is for regulated/safety contexts and should inform the DoD and Acceptance Criteria (11.1 / 11.3).' },
      { id: 'P8Q46', topic: 'RK', q: 'If Delivery Teams are in different time zones and Value Ownership availability is limited, what practical remedy does the PAQ guidance suggest?', options: ['Assign Business Analysts in each time zone to work locally and coordinate in overlapping hours', 'Cancel all refinement until everyone is co-located', 'Extend every Sprint to two months', 'Replace Value Ownership with the Scrum Master'], correct: 'Assign Business Analysts in each time zone to work locally and coordinate in overlapping hours', explain: 'Statement 9: plan events ahead, use as-needed availability, and use BAs across time zones (11.2.2.9).' },
      { id: 'P8Q47', topic: 'GV', q: 'For the Management Approach Definition, who is Responsible and who is Accountable?', options: ['Project Manager is Responsible; Business Sponsor is Accountable', 'Solution Architect is Responsible; Product Owner is Accountable', 'Scrum Master is Responsible; Developers are Accountable', 'Business Visionary is Responsible and Accountable'], correct: 'Project Manager is Responsible; Business Sponsor is Accountable', explain: 'MAD RACI: PM Responsible, BS Accountable; it is baselined at the end of Foundations (App. A).' },
      { id: 'P8Q48', topic: 'GV', q: 'Which of the following statements, about traditional \u2018compliance-based\u2019 governance, are true?\n1. It often inverts the Manifesto by favouring processes, documents, contracts and plans\n2. Signing off documents instead of talking to the customer can create a blame culture', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Inappropriate governance undermines agility; it is the Manifesto in reverse (12.1.1).' },
      { id: 'P8Q49', topic: 'GV', q: 'Agile project success, and therefore the focus of agile governance, depends on which of the following?\n1. Shared understanding\n2. Professionalism\n3. Collective expertise\n4. Maximum procedure regardless of outcome', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Highsmith: documentation is not understanding; governance should check the right things are done the right way (12.1.2).' },
      { id: 'P8Q50', topic: 'GV', q: 'For the Delivery Plan, who is both Responsible and Accountable?', options: ['Project Manager', 'Business Visionary', 'Product Owner', 'Scrum Master'], correct: 'Project Manager', explain: 'Delivery Plan RACI: PM is Responsible and Accountable; BV and SA contribute (App. A).' },
    ],
  },
  {
    id: 'hardI',
    title: 'Full Mock Exam 9',
    questions: [
      { id: 'P9Q1', topic: 'KC', q: 'In which month and year was the Agile Manifesto created, and by how many experts?', options: ['February 2001, by 17 experts at Snowbird, Utah', 'January 1994, by 12 experts in London', 'June 2010, by 8 experts in Boston', 'March 2005, by 17 experts in Silicon Valley'], correct: 'February 2001, by 17 experts at Snowbird, Utah', explain: 'The Manifesto was created in February 2001 at Snowbird by 17 software experts (2.1.3).' },
      { id: 'P9Q2', topic: 'KC', q: 'Identify the missing words. Leaders keep control of [ ? ]; self-organising team members are given authority over day-to-day tasks and how the work is done.', options: ['strategic direction (high-level goals and vision)', 'every task on the Sprint Backlog', 'the wording of every User Story', 'the Daily Scrum agenda only'], correct: 'strategic direction (high-level goals and vision)', explain: 'Empowerment is bounded: leaders hold strategy; teams hold day-to-day how (2.1.3).' },
      { id: 'P9Q3', topic: 'KC', q: 'Which of the following statements, about Scientific Management (Taylorism), are true?\n1. It promoted efficiency, economies of scale and strict procedure-following\n2. In extreme cases employees were treated like machines and not expected to understand the reasoning behind rules', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Taylorism shaped 20th-century work; its limits in a VUCA world drove the need for agility (2.1).' },
      { id: 'P9Q4', topic: 'KC', q: 'How does AgilePM define a customer?', options: ['Anyone \u2014 individual or organisation \u2014 who will benefit from, use or be affected by the project\u2019s work', 'Only the person who signs the supplier contract', 'Only the Business Sponsor', 'Only end users of software'], correct: 'Anyone \u2014 individual or organisation \u2014 who will benefit from, use or be affected by the project\u2019s work', explain: 'Customer is a broad term covering buyers, users and those affected (2.1.3).' },
      { id: 'P9Q5', topic: 'KC', q: 'Which of the following help explain why the last responsible moment is more efficient?\n1. It removes the need to estimate at all\n2. Near-future predictions are more reliable\n3. Less effort is wasted managing documents that go stale\n4. Decisions made later benefit from what has been learned and tested', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Deferring detail keeps it relevant; estimating is still required, just at the right precision (2.4).' },
      { id: 'P9Q6', topic: 'SC', q: 'Which events occur within the Sprint?', options: ['Sprint Planning, Daily Scrums, Sprint Review and Sprint Retrospective', 'Feasibility, Foundations, Deployment and Realisation', 'Only the Daily Scrum', 'Only the Project Increment Review'], correct: 'Sprint Planning, Daily Scrums, Sprint Review and Sprint Retrospective', explain: 'The Sprint is the container event for the other four events (3.5).' },
      { id: 'P9Q7', topic: 'SC', q: 'What is the Definition of Done?', options: ['A formal description of the state of the Increment when it meets the quality measures required for the product', 'A list of Must Have requirements only', 'The Sprint Goal by another name', 'A Gantt-chart milestone'], correct: 'A formal description of the state of the Increment when it meets the quality measures required for the product', explain: 'The Increment\u2019s commitment is the Definition of Done (3.6).' },
      { id: 'P9Q8', topic: 'SC', q: 'Which of the following statements, about the Scrum Team, are true?\n1. It contains no sub-teams or hierarchies\n2. It focuses on one objective at a time \u2014 the Product Goal', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'The Scrum Team is a cohesive unit of one Scrum Master, one Product Owner and Developers (3.4).' },
      { id: 'P9Q9', topic: 'SC', q: 'How does the Scrum Master serve the organisation?\n1. Owning the project budget and Business Case\n2. Leading, training and coaching the organisation in its Scrum adoption\n3. Planning and advising Scrum implementations\n4. Removing barriers between stakeholders and Scrum Teams', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Budget and Business Case sit with Value Ownership, not the Scrum Master (3.4 / 5.3.6).' },
      { id: 'P9Q10', topic: 'SC', q: 'Identify the missing words. Lean thinking reduces [ ? ] and focuses on [ ? ].', options: ['waste; essentials', 'feedback; contracts', 'transparency; reports', 'Sprints; Gantt charts'], correct: 'waste; essentials', explain: 'Scrum is founded on empiricism and lean thinking (3.2).' },
      { id: 'P9Q11', topic: 'SC', q: 'Who is responsible for estimating the size of Product Backlog items?', options: ['The Developers; the Product Owner can guide them with business understanding and trade-offs', 'The Business Sponsor alone', 'The Project Manager alone', 'The regulator'], correct: 'The Developers; the Product Owner can guide them with business understanding and trade-offs', explain: 'Those who do the work estimate it; the Product Owner provides value context (App. A / 8.3).' },
      { id: 'P9Q12', topic: 'AF', q: 'How does AgilePM help the Scrum Master beyond the Scrum Guide?', options: ['It gives a way to communicate with business leaders and project managers so teams get the support they need', 'It removes the Scrum Master role', 'It makes the Scrum Master the budget holder', 'It forbids the Scrum Master from facilitating events'], correct: 'It gives a way to communicate with business leaders and project managers so teams get the support they need', explain: 'AgilePM helps the SM engage the wider project organisation (4.4).' },
      { id: 'P9Q13', topic: 'AF', q: 'Which of the following statements, about \u2018Focus on the Business Need\u2019, are true?\n1. Every decision should be made with the project vision in mind\n2. The Business Visionary defines and communicates that vision', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'The PM ensures goals are clear and priorities realistic; BV communicates the vision (4.3).' },
      { id: 'P9Q14', topic: 'AF', q: 'Who provides quality oversight, with the Project Manager ensuring it happens?', options: ['Business Visionary, Solution Architect, Product Owner, and regulatory or other appropriate stakeholders', 'The Scrum Master alone', 'Developers with no other involvement', 'The investment board at year-end only'], correct: 'Business Visionary, Solution Architect, Product Owner, and regulatory or other appropriate stakeholders', explain: 'The Solution Architect sets the Definition of Done; those roles provide oversight (4.3).' },
      { id: 'P9Q15', topic: 'AF', q: 'Which of the following must the Value Ownership roles always have a clear understanding of?\n1. What will be delivered\n2. When it will be delivered\n3. How much it will cost\n4. Which Developer owns each task', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Under Deliver on Time, Value Ownership must know what, when and how much (4.3).' },
      { id: 'P9Q16', topic: 'AF', q: 'Identify the missing words. Common sense in AgilePM means using logical thinking and practical judgment instead of introducing [ ? ].', options: ['unnecessary complexity', 'any planning', 'any quality standard', 'any stakeholder'], correct: 'unnecessary complexity', explain: 'Common sense and pragmatism underpin the whole framework (4.1).' },
      { id: 'P9Q17', topic: 'IN', q: 'Which two things does Agile Leadership focus on?', options: ['Maximising transparency of the evolving problem/solution, and clearly defining who has authority to decide in each circumstance', 'Maximising documentation and centralising every decision', 'Removing the Product Owner and freezing the backlog', 'Replacing Scrum events with monthly reports'], correct: 'Maximising transparency of the evolving problem/solution, and clearly defining who has authority to decide in each circumstance', explain: 'Agile leaders also develop new leaders, not followers (5.1).' },
      { id: 'P9Q18', topic: 'IN', q: 'Which of the following statements, about Advisor roles, are true?\n1. Solution Advisors provide specialist \u2014 perhaps technical \u2014 input and may later become Developers\n2. Business Advisors advise on requirements, scenarios and regulatory compliance from a business perspective', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'The three Advisor roles are Business, Solution and Process (5.2).' },
      { id: 'P9Q19', topic: 'IN', q: 'On complex projects with multiple Delivery Teams sharing a Product Backlog, what should they create and work to?', options: ['A common Definition of Done, collaborating with the Solution Architect', 'A separate Definition of Done per Developer', 'No Definition of Done, to stay flexible', 'A Definition of Done owned only by the Business Sponsor'], correct: 'A common Definition of Done, collaborating with the Solution Architect', explain: 'Shared backlogs need a common DoD for a coherent solution (5.4).' },
      { id: 'P9Q20', topic: 'IN', q: 'Which of the following are Project Manager accountabilities?\n1. Managing the environment so self-management can happen\n2. Maintaining high-level planning artifacts while teams handle detailed planning\n3. Setting the Definition of Done\n4. Acting as final authority on delivery-enablement decisions', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The Solution Architect sets the Definition of Done (5.3.4).' },
      { id: 'P9Q21', topic: 'IN', q: 'Who should manage relationships with external stakeholders, facilitated by the Project Manager?', options: ['Business Visionary and Solution Architect', 'Developers only', 'The investment board only', 'The Process Advisor only'], correct: 'Business Visionary and Solution Architect', explain: 'BV and SA manage those relationships; the PM coordinates (5.2).' },
      { id: 'P9Q22', topic: 'IN', q: 'Organisations not wishing to use Scrum may use which equivalent AgilePM delivery-enablement role?', options: ['Team Leader', 'Business Ambassador', 'Investment chair', 'External auditor'], correct: 'Team Leader', explain: 'Team Leader is the equivalent of Scrum Master and should still aspire to servant/true leadership (5.3.6).' },
      { id: 'P9Q23', topic: 'IN', q: 'Identify the missing words. A Business Ambassador who is new to agile would likely work with [ ? ] than an experienced Product Owner.', options: ['fewer teams \u2014 perhaps just one', 'more than five teams immediately', 'no Delivery Team at all', 'only the Business Sponsor'], correct: 'fewer teams \u2014 perhaps just one', explain: 'An experienced PO may support up to three teams sharing one backlog; a new Ambassador typically supports fewer (5.4).' },
      { id: 'P9Q24', topic: 'CC', q: 'What does Active Listening include, according to AgilePM?', options: ['Pay attention, show you are listening, observe feelings, give constructive feedback, defer judgment, then respond appropriately', 'Interrupt quickly with the correct answer', 'Take notes only and never respond', 'Delegate listening to the Project Manager'], correct: 'Pay attention, show you are listening, observe feelings, give constructive feedback, defer judgment, then respond appropriately', explain: 'Active listening is one of the communication skills teams should inspect in retrospectives (6.3).' },
      { id: 'P9Q25', topic: 'CC', q: 'Which of the following statements, about documents in AgilePM, are true?\n1. Documents are created as formal records when they track assumptions, constraints, risks, decisions and commitments\n2. Documents may also show that the solution meets legal, regulatory or industry standards', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Those are the two key purposes of complementary AgilePM documents (6.4).' },
      { id: 'P9Q26', topic: 'CC', q: 'On the Aligned Autonomy Matrix, what does HIGH alignment combined with LOW autonomy produce?', options: ['An authoritative organisation with an authoritarian culture', 'An innovative organisation with a collaborative culture', 'An entrepreneurial organisation with a chaotic culture', 'A bureaucratic organisation with an indifferent culture'], correct: 'An authoritative organisation with an authoritarian culture', explain: 'High alignment + low autonomy = authoritative/authoritarian (Fig. 6.1).' },
      { id: 'P9Q27', topic: 'CC', q: 'A Delivery Team of specialists keep misunderstanding each other. Which action does AgilePM recommend first, and why can a glossary help?', options: ['Use a common, straightforward language \u2014 and keep a glossary of key terms when specialist language cannot be avoided', 'Switch entirely to email so everything is written down', 'Ask the Business Sponsor to rewrite every requirement', 'Ban face-to-face conversation so people have time to think'], correct: 'Use a common, straightforward language \u2014 and keep a glossary of key terms when specialist language cannot be avoided', explain: 'Cross-discipline teams need a shared language; a glossary prevents misunderstandings when jargon is unavoidable (6.3).' },
      { id: 'P9Q28', topic: 'PR', q: 'What does AgilePM use instead of Scrum\u2019s word \u2018Increment\u2019, and instead of the older term \u2018work-products\u2019?', options: ['Product Increment; Project Artifacts', 'Solution only; Work packages', 'Deployed Solution only; Registers', 'Epic; Modules'], correct: 'Product Increment; Project Artifacts', explain: 'v3 uses Product Increment for clarity and Project Artifacts instead of work-products (3.6 / 4.1).' },
      { id: 'P9Q29', topic: 'PR', q: 'Which of the following statements, about Delivery, are true?\n1. Delivery should include ongoing deployment of Solution Increments when feasible\n2. Realisation of value through measurement and feedback should also be ongoing where deployment is ongoing', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Delivery, Deployment and Realisation can run together rather than as strict sequential blocks (7.2).' },
      { id: 'P9Q30', topic: 'PR', q: 'The Project Review Report is updated when, and what should it capture?', options: ['At the end of each Project Increment; feedback on what was completed, lessons from the increment retrospective, and benefits that should now appear', 'At every Daily Scrum; individual performance scores', 'Only in Pre-Project; the original idea', 'Never; it is optional and empty'], correct: 'At the end of each Project Increment; feedback on what was completed, lessons from the increment retrospective, and benefits that should now appear', explain: 'It is a recommended evolutionary artifact, updated per increment (7.6 / App. A).' },
      { id: 'P9Q31', topic: 'PR', q: 'Identify the missing words. The Management Approach Definition is [ ? ] at the end of Foundations and changes later only if circumstances shift or a review suggests improvements.', options: ['baselined', 'deleted', 'handed to the regulator', 'converted into a Sprint Backlog'], correct: 'baselined', explain: 'MAD is recommended, evolutionary, and baselined after Foundations (App. A).' },
      { id: 'P9Q32', topic: 'PR', q: 'Which of the following are true of the Solution Backlog?\n1. By the end of Foundations a baseline defines project scope\n2. Major changes to the overall list (add, remove or significantly alter) must be formally controlled\n3. Depth/detail of a requirement is handled as scope creep\n4. The Business Visionary is both Responsible and Accountable for it', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Breadth changes are scope creep and use change control; depth uses MoSCoW contingency (8.2.4 / App. A).' },
      { id: 'P9Q33', topic: 'ES', q: 'A Solution-level Definition of Done is used when?', options: ['The solution is made of multiple interrelated products and must be complete, fit for business use and ready for operational deployment', 'There is only one Developer', 'The project has no Product Owner', 'MoSCoW is not being used'], correct: 'The solution is made of multiple interrelated products and must be complete, fit for business use and ready for operational deployment', explain: 'It reflects the SAD and DAD and includes integration, support readiness and stakeholder sign-off (8.2.3.7).' },
      { id: 'P9Q34', topic: 'ES', q: 'Which of the following statements, about Non-Functional Requirements, are true?\n1. They define how well the solution must perform\n2. They should be documented early in the outline Solution Architecture Definition because late discovery may make them impossible to include', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'NFRs belong in the SAD and must not be left until late Delivery (8.2.2 / 8.2.4).' },
      { id: 'P9Q35', topic: 'ES', q: 'Planning Poker is described as which style of estimating?', options: ['A consensus-based analogy technique using numbered cards', 'A mandate issued by the Business Sponsor', 'Bottom-up decomposition into hours only', 'A substitute for the Definition of Done'], correct: 'A consensus-based analogy technique using numbered cards', explain: 'Planning Poker is a variation of story-point / analogy estimating (8.3.3.1 / App. C).' },
      { id: 'P9Q36', topic: 'ES', q: 'Cost estimates should cover which scope, while benefit estimates should be based on which priorities?', options: ['Costs cover the full scope; benefits are based on Must Haves and Should Haves', 'Costs cover Must Haves only; benefits include Won\u2019t Haves', 'Both costs and benefits cover Could Haves only', 'Costs are not estimated in AgilePM'], correct: 'Costs cover the full scope; benefits are based on Must Haves and Should Haves', explain: 'Worst = Musts; Expected = Musts+Shoulds; Best = Musts+Shoulds+Coulds (9.7).' },
      { id: 'P9Q37', topic: 'ES', q: 'Which of the following are suggested Definition of Ready criteria?\n1. Clearly defined outcome and scope\n2. Value identified and aligned to the Product Goal\n3. Signed by the Business Sponsor as a fixed contract\n4. Dependencies, risks and estimates understood', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Ready is a shared understanding that the item can start \u2014 not a fixed-scope contract (8.2.3.5).' },
      { id: 'P9Q38', topic: 'ES', q: 'Tracking how many Should Haves and Could Haves are completed each increment or Sprint is useful because it can\u2026', options: ['Increase confidence if progress is good, and act as an early warning if too many non-critical items are at risk', 'Replace the need for a Business Case', 'Prove individual Developer rankings', 'Freeze MoSCoW priorities forever'], correct: 'Increase confidence if progress is good, and act as an early warning if too many non-critical items are at risk', explain: 'Should/Could completion is a health signal, not a guarantee of full scope (9.6).' },
      { id: 'P9Q39', topic: 'PC', q: 'Who approves Product Increments as fit for purpose at the end of a Sprint?', options: ['Business Visionary and Solution Architect', 'The investment board only', 'The Process Advisor only', 'Any stakeholder who sends an email'], correct: 'Business Visionary and Solution Architect', explain: 'Teams demonstrate the Done Increment; BV and SA approve fitness for purpose (10.4.1).' },
      { id: 'P9Q40', topic: 'PC', q: 'Which of the following statements, about unfinished backlog items, are true?\n1. They should be reviewed at the end of each Sprint and each Project Increment at a minimum\n2. Priorities should be continuously refined so the project stays aligned with business goals', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Unfinished work is re-ordered, not automatically carried forward at the same priority (10.2.3.11).' },
      { id: 'P9Q41', topic: 'PC', q: 'After Delivery Team Sprint Planning, what must the Project Manager do?', options: ['Update the Delivery Plan to reflect the emergent understanding and team commitments', 'Rewrite the Business Case from scratch', 'Cancel Cross-Team Refinement', 'Assign tasks to named Developers'], correct: 'Update the Delivery Plan to reflect the emergent understanding and team commitments', explain: 'Teams share Sprint Backlogs; the PM keeps the Delivery Plan current (10.2.3.4.4).' },
      { id: 'P9Q42', topic: 'PC', q: 'Which of the following are typical inputs to Cross-Team Refinement?\n1. Scrum artifacts plus the Business Case, Product Goals, Solution/Product Backlogs and Delivery Plan\n2. Possible outputs include refined artifacts, new Product Goals, and discussed dependencies/deployment plans\n3. Attendance is limited to the Business Sponsor and Business Visionary only\n4. Teams should experiment with who attends', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Project Roles and Product Owners plus team representatives attend; BS/BV are not the CTR audience (10.2.3.6.1).' },
      { id: 'P9Q43', topic: 'PC', q: 'Identify the missing words. Once increments are deployed, the [ ? ] Project Artifact can capture benefits accruing in the operational environment and may prompt further solution refinement.', options: ['Benefits Assessment', 'Terms of Reference', 'Sprint Backlog', 'Team Board'], correct: 'Benefits Assessment', explain: 'The value-realisation cycle runs Benefits Assessment \u2192 backlogs \u2192 increments (Fig. 10.12).' },
      { id: 'P9Q44', topic: 'RK', q: 'PAQ Statement 16 says progress is measured primarily through incremental delivery of demonstrable value. If a working Increment cannot be shown, what should teams do?', options: ['Improve discipline, integration or testing so each timebox produces something usable \u2014 and still find a way to show progress (prototype, test results)', 'Cancel all Sprint Reviews', 'Report percentage-complete against a Gantt chart instead', 'Reduce the Definition of Done until everything counts as Done'], correct: 'Improve discipline, integration or testing so each timebox produces something usable \u2014 and still find a way to show progress (prototype, test results)', explain: 'Visibility of value is the point; do not hide behind abstract metrics (11.2.2.16).' },
      { id: 'P9Q45', topic: 'RK', q: 'Which of the following statements, about commercial arrangements (PAQ Statement 17), are true?\n1. A fixed-price, fixed-specification contract appears to transfer risk to the supplier but still loses time and opportunity if the project fails\n2. The Agile Business Consortium publishes a sample Agile Project Framework contract template that can use techniques such as MoSCoW', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Work with procurement; if principles and roles are seriously undermined, AgilePM may not be the best fit (11.2.2.17).' },
      { id: 'P9Q46', topic: 'RK', q: 'If PAQ Statement 3 (the business vision is clearly stated and understood) is disagreed, who should explain the vision and what question should every decision be tested against?', options: ['The Business Visionary; \u2018Does this decision help us achieve the business vision?\u2019', 'The Scrum Master; \u2018Does this increase story points?\u2019', 'The regulator; \u2018Does this add a document?\u2019', 'The Developers; \u2018Does this extend the Sprint?\u2019'], correct: 'The Business Visionary; \u2018Does this decision help us achieve the business vision?\u2019', explain: 'If the answer is no or not sure, ask why the work is being done now (11.2.2.3).' },
      { id: 'P9Q47', topic: 'GV', q: 'For the Product Backlog, who is Responsible and who is Accountable?', options: ['Product Owner is Responsible; Business Visionary is Accountable', 'Developers are Responsible; Scrum Master is Accountable', 'Project Manager is Responsible; Business Sponsor is Accountable', 'Solution Architect is Responsible and Accountable'], correct: 'Product Owner is Responsible; Business Visionary is Accountable', explain: 'Product Backlog RACI: PO Responsible, BV Accountable (App. A).' },
      { id: 'P9Q48', topic: 'GV', q: 'Which of the following statements, about the Sprint Backlog RACI, are true?\n1. Developers are Responsible for the Sprint Backlog\n2. The Product Owner is Accountable for the Sprint Backlog', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Created by the Developers for the Developers, with the Product Owner accountable (App. A).' },
      { id: 'P9Q49', topic: 'GV', q: 'In Figure A.1, which statements about Project Artifact colours and markers are true?\n1. Orange artifacts focus on Value Ownership needs\n2. Green artifacts help build the solution being delivered\n3. Purple artifacts are about managing and controlling the project\n4. A (G) marker means the artifact must be printed in colour for the auditor', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Orange = value, green = solution, purple = management; (G) means the artifact may also support governance or gateway approval (App. A).' },
      { id: 'P9Q50', topic: 'GV', q: 'For the Sprint Review Record, who is Responsible, and in what situation is it treated as a governance artifact?', options: ['The Scrum Master / Team Leader is Responsible; it is a governance artifact when a formal, auditable record is required (for example in a regulated environment)', 'The Business Sponsor is Responsible; it is always informal', 'The Developers are Responsible; it replaces the Business Case', 'The Process Advisor is Responsible; it is only used in Pre-Project'], correct: 'The Scrum Master / Team Leader is Responsible; it is a governance artifact when a formal, auditable record is required (for example in a regulated environment)', explain: 'Accountable roles include SA, BV and PO; in regulated settings the record must be formal and auditable (App. A).' },
    ],
  },
]
